$ cat Alloc.java
public class Alloc {
    static Object sink;
    public static void main(String[] a) {
        int n = Integer.parseInt(a[0]);
        long t0 = System.nanoTime();
        for (int i = 0; i < n; i++) sink = new int[4];
        System.out.printf("%,d개 할당  %,d ms%n", n, (System.nanoTime()-t0)/1_000_000);
    }
}

